// V3-04 test ТЗ, generated by code (no binary files in the repository): three fictional businesses (no personal data)
// written once as structured sections and rendered to docx (fflate zip with WordprocessingML, Russian heading style ids
// as Word saves them), pdf (a minimal writer: Type0 font with a ToUnicode CMap, headings set larger than the body) and
// md; a short txt in Windows-1251 and KOI8-R. Each sample carries the recorded answer of the model (submit_brief_draft)
// and the brief sections the interview still has to ask about.
import { zipSync } from "fflate";
import type { BriefDraftAnswer, BriefGapSection } from "../src/brief-extract/index.js";

export interface TzSection {
  heading: string;
  paragraphs?: string[];
  items?: string[];
  /** A table under the heading (docx only; md and pdf render it as lines). */
  table?: string[][];
}

export interface TzSample {
  name: string;
  format: "docx" | "pdf" | "md";
  title: string;
  sections: TzSection[];
  /** The recorded answer of the model for this ТЗ (one chunk). */
  answer: BriefDraftAnswer;
  /** Sections briefGaps reports as missing after the model draft (interview order). */
  missing: BriefGapSection[];
  /** Missing sections that block the build. */
  blocking: BriefGapSection[];
}

/** A scenario «Когда <when>, система <steps>» (the contract field `then` is set here once). */
const sc = (s: Omit<BriefDraftAnswer["scenarios"][number], "then">, steps: string[]) => ({
  ...s,
  // biome-ignore lint/suspicious/noThenProperty: field name fixed by builder-v3.md §3 C1 («Когда…, система…»)
  then: steps,
});

