// ---- renderers -------------------------------------------------------------------------------------------------

/** Markdown of a sample: «# title», «## heading», «- item», paragraphs; a table as «| a | b |» rows. */
export function toMarkdown(s: TzSample): string {
  const out = [`# ${s.title}`];
  for (const sec of s.sections) {
    out.push(`## ${sec.heading}`);
    for (const p of sec.paragraphs ?? []) out.push(p);
    if (sec.items?.length) out.push(sec.items.map((i) => `- ${i}`).join("\n"));
    if (sec.table) out.push(sec.table.map((r) => `| ${r.join(" | ")} |`).join("\n"));
  }
  return `${out.join("\n\n")}\n`;
}

const xmlEscape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const run = (t: string) => `<w:r><w:t xml:space="preserve">${xmlEscape(t)}</w:t></w:r>`;
const para = (t: string, ppr = "") => `<w:p>${ppr ? `<w:pPr>${ppr}</w:pPr>` : ""}${run(t)}</w:p>`;

/** WordprocessingML of a sample with traps a reader must skip: deleted text, a field code, a fallback copy. */
export function docxXml(s: TzSample): string {
  const body: string[] = [para(s.title, '<w:pStyle w:val="a3"/>')];
  for (const sec of s.sections) {
    body.push(para(sec.heading, '<w:pStyle w:val="1"/>'));
    for (const p of sec.paragraphs ?? [])
      body.push(
        `<w:p><w:r><w:t>${xmlEscape(p)}</w:t></w:r><w:del w:id="9" w:author="x"><w:r><w:delText>удалённый текст</w:delText></w:r></w:del></w:p>`,
      );
    for (const i of sec.items ?? [])
      body.push(
        para(
          i,
          '<w:pStyle w:val="a5"/><w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr><w:tabs><w:tab w:val="left" w:pos="720"/></w:tabs>',
        ),
      );
    if (sec.table)
      body.push(
        `<w:tbl><w:tblPr/>${sec.table
          .map((r) => `<w:tr>${r.map((c) => `<w:tc><w:tcPr/>${para(c)}</w:tc>`).join("")}</w:tr>`)
          .join("")}</w:tbl>`,
      );
  }
  body.push(
    '<w:p><w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r></w:p>',
    '<w:p><w:r><mc:AlternateContent><mc:Choice Requires="wps"><w:t>надпись</w:t></mc:Choice><mc:Fallback><w:t>копия надписи</w:t></mc:Fallback></mc:AlternateContent></w:r></w:p>',
  );
  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006"><w:body>${body.join("")}<w:sectPr/></w:body></w:document>`;
}

// Russian Word saves heading styles with ids «1», «2» and the name «heading 1»; the list paragraph as «a5».
const STYLES = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
<w:style w:type="paragraph" w:default="1" w:styleId="a"><w:name w:val="Normal"/></w:style>
<w:style w:type="paragraph" w:styleId="1"><w:name w:val="heading 1"/><w:basedOn w:val="a"/><w:pPr><w:outlineLvl w:val="0"/></w:pPr></w:style>
<w:style w:type="paragraph" w:styleId="a3"><w:name w:val="Title"/><w:basedOn w:val="a"/></w:style>
<w:style w:type="paragraph" w:styleId="a5"><w:name w:val="List Paragraph"/><w:basedOn w:val="a"/></w:style>
</w:styles>`;

const enc = (s: string) => new TextEncoder().encode(s);

/** A docx file of a sample (zip: content types, relationships, document, styles). */
export function toDocx(s: TzSample): Uint8Array {
  return zipSync({
    "[Content_Types].xml": enc(
      '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>',
    ),
    "_rels/.rels": enc(
      '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>',
    ),
    "word/document.xml": enc(docxXml(s)),
    "word/styles.xml": enc(STYLES),
  });
}

/** Lines of a pdf page: text and font size. */
type PdfText = { text: string; size: number };

function pdfLines(s: TzSample): PdfText[] {
  const out: PdfText[] = [{ text: s.title, size: 18 }];
  for (const sec of s.sections) {
    out.push({ text: sec.heading, size: 14 });
    for (const p of sec.paragraphs ?? []) out.push({ text: p, size: 11 });
    for (const i of sec.items ?? []) out.push({ text: `• ${i}`, size: 11 });
    for (const r of sec.table ?? []) out.push({ text: r.join("   "), size: 11 });
  }
  return out;
}

/** UTF-16 code units → hex for Identity-H text; only the ranges the ToUnicode CMap below covers. */
function hex(text: string): string {
  return [...text]
    .map((ch) => {
      const c = ch.codePointAt(0) as number;
      if (!(c < 0x100 || (c >= 0x400 && c < 0x500) || (c >= 0x2000 && c < 0x2200)))
        throw new Error(`pdf fixture: no glyph range for «${ch}»`);
      return c.toString(16).padStart(4, "0").toUpperCase();
    })
    .join("");
}

const TO_UNICODE = `/CIDInit /ProcSet findresource begin
12 dict begin
begincmap
/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def
/CMapName /Adobe-Identity-UCS def
/CMapType 2 def
1 begincodespacerange
<0000> <FFFF>
endcodespacerange
4 beginbfrange
<0000> <00FF> <0000>
<0400> <04FF> <0400>
<2000> <20FF> <2000>
<2100> <21FF> <2100>
endbfrange
endcmap
CMapName currentdict /CMap defineresource pop
end
end`;

/** Wraps a line at `width` characters (the pdf has no layout engine). */
function wrap(text: string, width: number): string[] {
  const out: string[] = [];
  let cur = "";
  for (const w of text.split(" ")) {
    if (cur && cur.length + 1 + w.length > width) {
      out.push(cur);
      cur = w;
    } else cur = cur ? `${cur} ${w}` : w;
  }
  if (cur) out.push(cur);
  return out;
}

/** A minimal pdf of text lines: A4 pages, a Type0 font with Identity-H and ToUnicode (text extraction only). */
export function pdfOf(lines: readonly PdfText[], opts: { perPage?: number } = {}): Uint8Array {
  const perPage = opts.perPage ?? 40;
  const placed: { text: string; size: number }[] = lines.flatMap((l) =>
    wrap(l.text, l.size > 11 ? 60 : 85).map((t) => ({ text: t, size: l.size })),
  );
  const pages: (typeof placed)[] = [];
  for (let i = 0; i < placed.length; i += perPage) pages.push(placed.slice(i, i + perPage));
  const objs: string[] = [];
  /** Adds an object; returns its number (1-based). */
  const add = (body: string) => objs.push(body);
  const stream = (dict: string, data: string) =>
    `<< ${dict} /Length ${data.length} >>\nstream\n${data}\nendstream`;
  const catalog = add("");
  const pagesObj = add("");
  const toUnicode = add(stream("", TO_UNICODE));
  const descriptor = add(
    "<< /Type /FontDescriptor /FontName /WizardFixture /Flags 32 /FontBBox [0 -200 1000 900] /ItalicAngle 0 /Ascent 900 /Descent -200 /CapHeight 700 /StemV 80 >>",
  );
  const cid = add(
    `<< /Type /Font /Subtype /CIDFontType2 /BaseFont /WizardFixture /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor ${descriptor} 0 R /DW 500 /CIDToGIDMap /Identity >>`,
  );
  const font = add(
    `<< /Type /Font /Subtype /Type0 /BaseFont /WizardFixture /Encoding /Identity-H /DescendantFonts [${cid} 0 R] /ToUnicode ${toUnicode} 0 R >>`,
  );
  const kids: number[] = [];
  for (const [n, page] of pages.entries()) {
    let y = 800;
    const ops = page.map((l) => {
      y -= l.size * 1.5;
      return `BT /F1 ${l.size} Tf 50 ${y.toFixed(1)} Td <${hex(l.text)}> Tj ET`;
    });
    ops.push(`BT /F1 9 Tf 290 30 Td <${hex(String(n + 1))}> Tj ET`);
    const content = add(stream("", ops.join("\n")));
    kids.push(
      add(
        `<< /Type /Page /Parent ${pagesObj} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${content} 0 R >>`,
      ),
    );
  }
  objs[catalog - 1] = `<< /Type /Catalog /Pages ${pagesObj} 0 R >>`;
  objs[pagesObj - 1] =
    `<< /Type /Pages /Kids [${kids.map((k) => `${k} 0 R`).join(" ")}] /Count ${kids.length} >>`;
  let out = "%PDF-1.7\n%\xE2\xE3\xCF\xD3\n";
  const offsets: number[] = [];
  for (const [i, body] of objs.entries()) {
    offsets.push(out.length);
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  }
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n${offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("")}`;
  out += `trailer\n<< /Size ${objs.length + 1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Uint8Array.from(out, (c) => c.charCodeAt(0));
}

/** A pdf of a sample: title 18 pt, headings 14 pt, body 11 pt, list items with «•». */
export const toPdf = (s: TzSample): Uint8Array => pdfOf(pdfLines(s));

/** The file of a sample in its format. */
export function sampleFile(s: TzSample): Uint8Array {
  if (s.format === "docx") return toDocx(s);
  if (s.format === "pdf") return toPdf(s);
  return enc(toMarkdown(s));
}

/** Encodes text in an 8-bit code page (the inverse of TextDecoder), for Windows-1251 and KOI8-R fixtures. */
export function encode8bit(text: string, label: "windows-1251" | "koi8-r"): Uint8Array {
  const dec = new TextDecoder(label);
  const table = new Map<string, number>();
  for (let b = 0; b < 256; b++) table.set(dec.decode(Uint8Array.of(b)), b);
  return Uint8Array.from([...text], (ch) => {
    const b = table.get(ch);
    if (b === undefined) throw new Error(`${label}: no byte for «${ch}»`);
    return b;
  });
}

